export type ApiErrorCode = "INVALID_ARGUMENT" | "UNKNOWN_OPERATION" | "DEVICE_MISMATCH" | "NOT_IMPLEMENTED" | "UNVERIFIED" | "DISABLED_OPERATION" | "DEVICE_NOT_READY" | "DEPENDENCY_MISSING" | "READBACK_MISMATCH" | "ADAPTER_ERROR" | "INVALID_RESPONSE" | "UNSUPPORTED_FORMAT" | "NOT_FOUND" | "CONFLICT" | "STORAGE_ERROR";
export type Response<K extends Operation> = ({ apiVersion: 1; requestId: string; deviceId: DeviceId | null; operation: string | null } & ({ ok: true; data: FeatureOperations[K]["result"]; meta: { observedAt: string; implementation: "implemented"; effect: string; evidence: string } } | { ok: false; error: { code: ApiErrorCode; message: string; retryable: boolean } }));
export interface Capability { id: Operation; title: string; devices: DeviceId[]; effect: "read" | "write" | "local" | "destructive"; availability: "implemented" | "planned" | "unverified" | "disabled"; evidence: string; reason: string; auditIds: string[]; canInvoke: boolean; deviceReadiness: "not-probed"; apiVersion: 1; args: Record<string, unknown>; result: Record<string, unknown> }
export interface FeatureApi { list(query?: { deviceId?: DeviceId }): Promise<{ apiVersion: 1; deviceReadiness: "not-probed"; operations: Capability[] }>; describe(operation: Operation): Promise<Capability | null>; invoke<K extends Operation>(request: Request<K>): Promise<Response<K>>; }
